export const CATEGORIAS_PRODUCTOS_BASE: CategoriaProducto[] = ARBOL.map(expandirCategoria)

// Id de la categoría donde cae, por defecto, cualquier rubro de
// producto nuevo que no se le asignó explícitamente una categoría.
export const CATEGORIA_PRODUCTO_FALLBACK_ID = 'otros-productos'

// Categorías que ya no existen como tales: lo que el admin haya
// agregado o movido a ellas va a su nueva categoría.
export const CATEGORIA_PRODUCTO_ALIAS: Record<string, string> = {
  calzado: 'ropa',
  accesorios: 'ropa',
}

// Compatibilidad con productos viejos: antes de esta clasificación,
// `producto.categoria` guardaba directamente uno de estos 4 nombres
// fijos. Este mapa se usa una sola vez, al leer un producto que
// todavía no tiene `rubro`, para no perder su clasificación.
export const LEGACY_CATEGORIA_A_RUBRO: Record<string, string> = {
  Calzado: 'otro-calzado',
  Ropa: 'otro-ropa',
  Accesorios: 'otro-accesorio',
  Hogar: 'otro-hogar',
}

// Si un producto quedó con el id de una SUBCATEGORÍA que no es a la vez
// un rubro (ej: 'ropa-calzado'), se lo lee como el "Otros" de esa
// subcategoría para que no quede sin clasificar.
export const RUBRO_DE_GRUPO: Record<string, string> = (() => {
  const hojas = new Set(CATEGORIAS_PRODUCTOS_BASE.flatMap((c) => c.rubros.map((r) => r.id)))
  const m: Record<string, string> = {}
  for (const c of CATEGORIAS_PRODUCTOS_BASE) {
    for (const r of c.rubros) {
      if (!r.grupoId || hojas.has(r.grupoId) || m[r.grupoId]) continue
      const delGrupo = c.rubros.filter((x) => x.grupoId === r.grupoId)
      m[r.grupoId] = (delGrupo.find((x) => /^otros?$/i.test(x.label)) || delGrupo[delGrupo.length - 1]).id
    }
  }
  return m
})()
